window.RULES_DATA = {"title":"New Horizons Roleplay — Rules & Regulations","revised":"September 26, 2026","intro":"Welcome to New Horizons Roleplay, where every decision shapes your destiny. New Horizons RP is a serious and immersive roleplay server built for players who value realism, depth, and the opportunity for a true fresh start. Whether you’re rising through the ranks of a powerful gang, serving the community within a structured and professional law enforcement agency, or building your path through a detailed and rewarding economy, every choice you make helps define your story. This is your city. This is your roleplay.","sections":[{"title":"General Rules","items":[{"text":"All players must be 18+ to be Whitelisted in NHRP.","level":0},{"text":"Must show proficiency in English as this is an English-Only Server.","level":0},{"text":"Anyone caught lying about their age will receive a permanent ban.","level":0},{"text":"Always treat other players and staff with respect.","level":0},{"text":"Toxic behavior, harassment, racism, sexism, hate speech, or drama (in or out of the server) will not be tolerated and will result in a permanent ban.","level":0},{"text":"Actions that disrupt or conflict with others’ roleplay scenes are prohibited.","level":0},{"text":"Leaking or distributing server information (including internal discussions, decisions, or content) without leadership approval will result in removal of whitelist access and further punishment.","level":0},{"text":"Talking negatively about NHRP or the staff team will result in a permanent ban with no appeal.","level":0},{"text":"Racial slurs, sexual harassment is a ZERO tolerance and will result in an immediate permanent ban without appeal.","level":0},{"text":"Players are responsible for reading and understanding all rules.","level":0},{"text":"All violations will be handled based on severity and evidence.","level":0},{"text":"Reporting players must include clip evidence with audio.","level":0},{"text":"Rules can be changed, modified, or removed at any time with or without notification to the players.","level":0},{"text":"Real-Money Transactions: Players are strictly prohibited from requesting, accepting, or sending IRL money to another player for any NHRP business, vehicle, item, service, or in-city asset; all IRL transactions must be conducted directly between the player and NHRP.","level":0}],"category":"General Rules"},{"title":"Character Regulations","items":[{"text":"All characters must be aged 18 or older.","level":0},{"text":"Your characters must vary in name, appearance, and mannerisms.","level":0},{"text":"Characters should be customized.","level":0},{"text":"Non-Human roleplay is not permitted.","level":0},{"text":"All players must roleplay as their gender assigned at birth. Transexual roleplay is not allowed at NHRP.","level":0}],"category":"Roleplay Standards"},{"title":"Staying in Character","items":[{"text":"If another player breaks any rule, you must remain in character and do your best to keep the integrity of the roleplay scene, clip the violation, and make a ticket for it to be handled by the staff team. No out of character talk in-city.","level":0},{"text":"Injuries must be roleplayed realistically","level":0}],"category":"Roleplay Standards"},{"title":"Fail RP","items":[{"text":"An action that breaks the immersion of the roleplay scenario.","level":0},{"text":"If you couldn’t do it in real life, you shouldn’t do it on the server.","level":0},{"text":"Disrupting immersion through unrealistic or trolling behavior.","level":0},{"text":"Example: /me messages that are not direct roleplay related. Using /me to trash talk is not considered a roleplay purpose.","level":1},{"text":"Mentioning the rules (bible reference), staff (angels), or threatening to send a prayer is considered fail rp and low quality roleplay. If you are in a situation that rules are violated and it is not an extreme situation, you are to let the scene play out, clip the scene, and report it afterwards without disrupting the roleplay.","level":0}],"category":"Roleplay Standards"},{"title":"Repetitive RP","items":[{"text":"Repeating the same RP back-to-back or day-to-day. Character’s priorities should vary after every scenario and day.","level":0},{"text":"Example: Running the same heist back to back. Or consistently resorting to shooting instead of other types of RP.","level":1}],"category":"Roleplay Standards"},{"title":"Low Quality Roleplay","items":[{"text":"Killing another player for the sole purpose of robbing them is considered low-quality RP.","level":0},{"text":"Robberies must involve meaningful roleplay with valid in-character reasons. Pocket wiping without valid in-character reason is considered low quality roleplay.","level":0},{"text":"LEO Cuffing someone while EMS is actively treating a suspect is not permitted.","level":0},{"text":"LEO may cuff the suspect(s) prior to EMS treating them, if applicable.","level":1},{"text":"Gunplay Over Roleplay is Prohibited: Gunplay is a player choosing gun violence over verbal interaction and continuously has interactions with a firearm involved. There are other ways scenes can go without someone ending up shot every time.","level":0}],"category":"Roleplay Standards"},{"title":"After Dark RP","items":[{"text":"Lowering your quality of RP when the current population is at a lower count.","level":0}],"category":"Roleplay Standards"},{"title":"Intrusive RP","items":[{"text":"Characters should not be inserting themselves into active scenarios they are not a part of without significant reason.","level":0},{"text":"Intentionally provoking police (revving, honking, committing crimes in front of them) is not allowed.","level":0}],"category":"Roleplay Standards"},{"title":"Lootboxing RP","items":[{"text":"Looting characters/vehicles without sufficient roleplay.","level":0},{"text":"Looting characters/vehicles when you were not part of the original scenario.","level":0}],"category":"Roleplay Standards"},{"title":"Asset Transferring","items":[{"text":"Transferring items to other players before killing off a character is prohibited. This includes paid items through the tebex.","level":0},{"text":"Items may not be transferred from one personal character to another. Do not assist in doing so or you can be disciplined as well.","level":0}],"category":"Roleplay Standards"},{"title":"Metagaming","items":[{"text":"Using knowledge obtained out of character for your own or others’ advantage. This includes chatting in a discord call to relay in-game knowledge.","level":0},{"text":"All in-character communication must be face-to-face, phone, or radio, using discord VC or any other method of communication for in-character conversation is metagaming.","level":0},{"text":"Metagaming will result in an automatic permanent ban","level":0}],"category":"Game Mechanics"},{"title":"Powergaming","items":[{"text":"Forcing actions without giving others a chance to react or roleplaying unrealistic abilities is prohibited.","level":0},{"text":"Prioritize roleplay over winning. Having a winning mentality falls under powergaming.","level":0},{"text":"Gunplay Over Roleplay is Prohibited: Gunplay is a player choosing gun violence over verbal interaction and continuously has interactions with a firearm involved. There are other ways scenes can go without someone ending up shot every time.","level":0},{"text":"Killing another player for the sole purpose of robbing them is considered low-quality RP.","level":0},{"text":"Camping drug locations with the sole intent to kill and rob is prohibited.","level":0},{"text":"Character Knowledge Separation: Information cannot transfer between your characters.","level":0}],"category":"Game Mechanics"},{"title":"Stream Sniping","items":[{"text":"It is prohibited to watch a live stream of any streamer on any platform actively streaming NHRP while you are in city.","level":0},{"text":"Intentional stream interference will result in a non-appealable ban from NHRP.","level":0},{"text":"Stream Sniping will result in an automatic permanent ban.","level":0}],"category":"Game Mechanics"},{"title":"Interaction & Escalation Rules","items":[{"text":"NHRP is a Serious Roleplay community. Interactions should prioritize immersion, storytelling, realism, and meaningful character development over “winning” scenes through violence.","level":0},{"text":"Violence is intended to be a last resort not the default outcome of every disagreement or interaction.","level":0}],"category":"Crime & Conflict"},{"title":"Escalation Standards","items":[{"text":"All hostile or violent interactions must involve reasonable escalation and meaningful roleplay leading up to the conflict.","level":0},{"text":"Hostage Restrictions – Criminals are limited to one demand per hostage during hostage negotiations. Multiple demands require multiple hostages.","level":0},{"text":"The following alone does NOT justify shootings, executions, kidnappings, or violent retaliation:","level":0},{"text":"verbal disrespect","level":1},{"text":"insults","level":1},{"text":"“talking crazy”","level":1},{"text":"staring","level":1},{"text":"minor arguments","level":1},{"text":"driving behavior","level":1},{"text":"social media posts","level":1},{"text":"or isolated confrontations without ongoing RP context.","level":1},{"text":"Players are expected to create depth within interactions through:","level":0},{"text":"negotiations","level":1},{"text":"intimidation","level":1},{"text":"demands","level":1},{"text":"hostage situations","level":1},{"text":"robberies","level":1},{"text":"retreats","level":1},{"text":"compromises","level":1},{"text":"or long-form conflict development before escalating to lethal force.","level":1},{"text":"Immediate escalation to gun violence without meaningful roleplay buildup may be considered Low Quality Roleplay or FailRP.","level":0}],"category":"Crime & Conflict"},{"title":"Fear of Life and Injury","items":[{"text":"Your character must realistically value their life and physical safety at all times.","level":0},{"text":"Players may not:","level":0},{"text":"recklessly rush active gunfire,","level":1},{"text":"intentionally seek death to avoid consequences,","level":1},{"text":"ignore overwhelming odds,","level":1},{"text":"or repeatedly force shootouts with no regard for realistic fear or injury.","level":1},{"text":"Do not be the hero. If you are realistically outnumbered or in a situation where you have little to no chance of survival, you must realistically fear for your life.","level":2},{"text":"Characters are expected to surrender, retreat, negotiate, or comply when realistically appropriate.","level":1},{"text":"“Win mentality” roleplay where the sole objective is killing, escaping, or avoiding jail is not considered Serious Roleplay.","level":1},{"text":"Repeated reckless behavior, constant menace behavior, or disregard for realistic fear, injury, and consequences may be considered Fail RP and result in disciplinary action","level":1}],"category":"Crime & Conflict"},{"title":"Retaliation and Revenge RP","items":[{"text":"Retaliation must involve meaningful roleplay development and time progression.","level":0},{"text":"Players may not:","level":0},{"text":"immediately regroup and retaliate after losing a scene","level":1},{"text":"continuously return to the same conflict","level":1},{"text":"or engage in nonstop revenge cycles","level":1},{"text":"Revenge attacks solely motivated by losing weapons, money, territory, or pride are not valid roleplay.","level":0},{"text":"Nonstop violent interactions with little to no roleplay depth may be considered Low Quality RP even if no specific rule is technically broken.","level":0},{"text":"Staff reserve the right to intervene in scenes or issue punishments when interactions clearly damage the quality and realism of the server environment.","level":0}],"category":"Crime & Conflict"},{"title":"Random Deathmatch (RDM)","items":[{"text":"Attacking a player or group without proper interaction.","level":0},{"text":"Gunplay Over Roleplay is Prohibited: Gunplay is a player choosing gun violence over verbal interaction and continuously has interactions with a firearm involved. There are other ways scenes can go without someone ending up shot every time.","level":0}],"category":"Crime & Conflict"},{"title":"Vehicular Deathmatch (VDM)","items":[{"text":"Using your vehicle to kill other players without any interaction.","level":0}],"category":"Crime & Conflict"},{"title":"Combat Mechanic Exploiting","items":[{"text":"Abusing stun mechanics to prevent others from moving or retaliating.","level":0},{"text":"Glitch fighting","level":0},{"text":"Excessive tackling","level":0},{"text":"Looting bodies you or your group did not kill is prohibited.","level":0}],"category":"Crime & Conflict"},{"title":"Combat Logging","items":[{"text":"Intentionally disconnecting to avoid roleplay scenarios and their consequences.","level":0},{"text":"If you crash during a scene, you must notify staff, or return within five minutes.","level":0},{"text":"Combat Logging will result in an 5 day temp ban for first offense -> Permanent Ban for second offense","level":0}],"category":"Crime & Conflict"},{"title":"New Life Rule","items":[{"text":"You may not return to the place of your death for at least 60 minutes","level":0},{"text":"If EMS body-bags you, you are considered nonrevivable and you will not remember any details that led up to you being killed, and recording software may be used.","level":0},{"text":"If you “see the light” this is considered flatbacked and loses the last 60 IRL minutes of the scene and cannot return to the area of the scene.","level":0},{"text":"The only exception to this is only if EMS is not on duty. However, you still cannot return to the original area of the scene.","level":1},{"text":"If EMS treats you roadside or at the hospital, you are not considered new life and still can be arrested by law enforcement.","level":0},{"text":"If a player is shot or injured by melee and placed on their side, they may not be medically treated to re-enter the same scene. Knockouts are excluded from this rule. EMS will only treat when the active scene is complete.","level":0},{"text":"If a Law Enforcement Officer (LEO) is treated and revived by EMS at the scene, they may return only to process and arrest suspects, if applicable. They may not rejoin the fight or engage in gunfire unless they are defending themselves after being attacked again.","level":0}],"category":"General Rules"},{"title":"Value of Life","items":[{"text":"You must fear for your life if you are put in danger. If you are outnumbered or have a weapon pulled on you, you are required to fear.","level":0},{"text":"Criminal characters are expected to show realistic fear and awareness of law enforcement at all times. Ambushing police without proper build-up, returning to active scenes, baiting officers or locals, interfering without valid RP reason, or escalating every encounter into violence will be considered Fail RP. You must roleplay with self-preservation and value of freedom in mind, meaning your character recognizes real consequences such as prison time, serious injury, or death, and does not treat LEO action as a minor inconvenience. Killing officers, mass drug crimes, running over police, or acting as a constant menace in every interaction is not realistic and will not be tolerated. Criminal RP should reflect tension, caution, and consequence, not reckless escalation. Repeated menace behavior or disregard for realism will result in disciplinary action for Fail RP.","level":0}],"category":"Crime & Conflict"},{"title":"Realistic Vehicle Operation","items":[{"text":"If your vehicle is damaged, you may repair it using a repair kit.","level":0},{"text":"If the damage occurred during an active roleplay scene, civilian players must request roadside assistance from a mechanic or towing company.","level":0},{"text":"LEOs may use a repair kit on their patrol vehicle during an active scene but may not immediately rejoin a pursuit or combat after repairing it.","level":0}],"category":"Game Mechanics"},{"title":"Priority Cooldown","items":[{"text":"To promote realistic pacing, meaningful consequences, and higher-quality roleplay, NHRP enforces a mandatory Priority Crime Cooldown.","level":0},{"text":"Rob same person cooldown: Once per restart.","level":0},{"text":"Any player involved in a priority interaction with law enforcement must wait 60 real-life minutes before initiating or participating in another priority crime scene.","level":0},{"text":"The 60-minute cooldown begins after the conclusion of any of the following:","level":0},{"text":"Police pursuit / vehicle chase","level":1},{"text":"Shootout or armed confrontation with law enforcement","level":1},{"text":"Arrest for any criminal offense, once you are placed in prison (regardless of charge severity)","level":1},{"text":"Each qualifying interaction resets the cooldown timer.","level":0},{"text":"The following is restricted during a cooldown:","level":0},{"text":"Initiate or participate in priority crimes (robberies, armed crimes, gang hits, planned shootouts, high-risk criminal scenarios)","level":1},{"text":"Escalate situations into priority scenes involving police","level":1},{"text":"What is allowed during a cooldown:","level":0},{"text":"Passive or low-impact roleplay","level":1},{"text":"Civilian RP, social RP, employment RP","level":1},{"text":"Court, jail, medical, or legal RP related to the prior incident","level":1},{"text":"Non-escalatory interactions with law enforcement","level":1},{"text":"Defensive action(s) against another player or group.","level":1}],"category":"Crime & Conflict"},{"title":"E-Relationships","items":[{"text":"Relationship RP is allowed as long as both parties are above the age of 18 and consent to all scenes related to ERP.","level":0},{"text":"If you choose to engage in relationships online. Both parties are to ensure that there is no drama that pours into the server over their relationship. Drama caused by relationships developed within the NHRP community can and will result in both parties being banned from NHRP.","level":0}],"category":"Roleplay Standards"},{"title":"AI/Local Traffic","items":[{"text":"Killing AI/Local traffic without any valid roleplay reason is prohibited.","level":0}],"category":"Roleplay Standards"},{"title":"Hostage Restrictions","items":[{"text":"No fake hostages or friends as hostages.","level":0},{"text":"You must have proper roleplay reasoning to kidnap someone, you cannot do it just for fun.","level":0},{"text":"Limited to one demand per hostage during hostage negotiations. Multiple demands require multiple hostages.","level":0},{"text":"Not able to ask for free passage during hostage negotiations.","level":0},{"text":"If a demand is made during hostage negotiations, the hostage must be exchanged before leaving.","level":0},{"text":"There must be at least 8 LEO on duty for LEO to be kidnapped.","level":0},{"text":"On-duty EMS personnel are considered passive roleplay participants and may not be taken hostage.","level":0}],"category":"Crime & Conflict"},{"title":"Staff Discretion","items":[{"text":"All roleplay scenes and player actions are subject to staff discretion when it comes to evaluating roleplay quality. This includes things like low-effort RP, showing no real intent to roleplay, cop-baiting, and similar issues. Use common sense, if you aren’t sure, open a ticket to discuss prior to starting the scene. Everyone must value their life and freedom at all times. Continual chaos, nonstop police chases, improper vehicle operation, ocean-dumping vehicles/bodies, or general “menace” behavior will not be tolerated. Focus on creating immersive, meaningful roleplay.","level":0},{"text":"Server Director and up can revoke whitelist status at any time.","level":0}],"category":"General Rules"},{"title":"Game Mechanics","items":[{"text":"Usage of any third-party software in order to hack or cheat is not permitted.","level":0},{"text":"Discovery of any bug that is not immediately reported and is continued use to create an unfair advantage is prohibited.","level":0},{"text":"The use of any graphics, visual, or sound mods that provide a combat or tactical advantage is strictly prohibited. This includes, but is not limited to, mods that increase brightness at night, remove or reduce grass, water, fog, or other environmental elements, or enhance audio to better locate players. All PvP-advantage mods are forbidden on NHRP.","level":0},{"text":"Players are not allowed to jump, climb, boost, or otherwise bypass walls, fences, gates, or barriers to enter or exit a Motorcycle Club compound or faction compound unless there is a clearly accessible RP entrance such as a gate, door, or open access point.","level":0},{"text":"Entering an MC compound by jumping walls, using vehicles to boost over, or exploiting map geometry is considered FailRP and exploiting.","level":1},{"text":"Use of Tactical Visual Mods will result in an automatic permanent ban","level":0}],"category":"Game Mechanics"},{"title":"Player Reports, Tickets, and Bans","items":[{"text":"All player reports must be submitted through the Discord or in game by using t/reports.","level":0},{"text":"Open a ticket in discord under the Tickets Channel on discord.","level":0},{"text":"Do not direct message staff or owner about ticket needs.","level":0},{"text":"Hostility towards staff may result in a ban.","level":0},{"text":"Sharing information discussed in tickets is prohibited and will lead to disciplinary action.","level":0},{"text":"Reports are handled on a case-by-case basis depending on severity.","level":0},{"text":"Spamming tickets or pinging staff can result in a permanent Discord ban or a time-out.","level":0},{"text":"To report staff, open a support ticket to the Server Directors.","level":0},{"text":"Include video/audio clip evidence for reports. Without clips, your allegation cannot be sustainable","level":0}],"category":"Community & Reports"},{"title":"Advertising Other Servers","items":[{"text":"Promoting or advertising other servers in-game or in Discord is not allowed.","level":0},{"text":"Advertising through DMs or server channels without approval will result in a permanent ban.","level":0},{"text":"If your discord is hacked or sending spam or phishing content in the discord or to discord members DM, your account will be banned from the discord for security purposes. If you are unable to recover your account, you are not guaranteed to receive item(s) or money that your character(s) had on your account.","level":0}],"category":"Community & Reports"},{"title":"FIRE/EMS Rules","items":[{"text":"On-duty EMS personnel are considered passive roleplay participants and may not be taken hostage. This protection applies only while they are actively performing their job duties.","level":0},{"text":"Intentionally harming or killing Fire or EMS personnel is prohibited.","level":0},{"text":"If Fire/EMS personnel knowingly place themselves in a dangerous or active scene and are injured as a result, they assume responsibility for their actions. Players are not required to alter or stop roleplay to protect Fire/EMS personnel who voluntarily enter a hazardous area.","level":1},{"text":"EMS must clear you after treatment is complete and billed, if applicable prior to you walking away from the scene.","level":0},{"text":"Respect EMS instructions on scene.","level":0},{"text":"Injuries must be roleplayed realistically.","level":0},{"text":"Dead or injured bodies must remain on scene, regardless of whether the player presses the keybind to request EMS. The only exception is when law enforcement transports a victim after notifying EMS and obtaining clearance to do so, or if EMS is not on duty.","level":0},{"text":"Do not “see the light” if EMS is actively treating.","level":0},{"text":"Players must have at least 7 days of playtime in the city before applying to Fire or EMS.","level":0},{"text":"You are not allowed to take any ems equipment from robberies or dead people.","level":0},{"text":"You are not allowed to steal EMS Vehicles.","level":0}],"category":"EMS / Fire & Media"},{"title":"Streaming Rules","items":[{"text":"Streamers must apply for the Streamer Role and have content approved before posting or live-streaming NHRP on any platform.","level":0},{"text":"Ads, videos, pictures, and clips cannot be shared publicly without approval.","level":0},{"text":"Content creators must speak positively about the server on all platforms and content. Any questions, comments, or concerns should be brought to the attention of staff via tickets.","level":0},{"text":"Server Director and above has the right to revoke Streamer Role at any time for any reason.","level":0}],"category":"EMS / Fire & Media"},{"title":"Police / LEO Rules","items":[{"text":"A minimum 1-minute interaction is required before any violence.","level":0},{"text":"LEO powers/equipment must not be abused.","level":0},{"text":"LEOs must operate their vehicles using realistic driving dynamics rules.","level":0},{"text":"Complaints about officers should follow the department chain of command or through the DOJ. If you feel that server rules were violated, open a ticket.","level":0},{"text":"Mass killing LEO is forbidden without proper interaction.","level":0},{"text":"Transfers require approval from both department heads and at least 1 month of service in the current department.","level":0},{"text":"LEO Cannot camp out at known criminal locations, such as drug locations or hidden crafting locations.","level":0},{"text":"F9 and 1 of 1 Guns","level":0},{"text":"LEOs may remove attachments and ammunition from F9 or 1-of-1 weapons.","level":1},{"text":"LEOs may not seize F9 or 1-of-1 weapons as evidence.","level":1},{"text":"Officers must document the weapon and its description in their report before returning it to the player's inventory.","level":1},{"text":"These weapons do not exempt a player from being charged with any applicable Felon in Possession offenses.","level":1},{"text":"Players may not rob LEOs or steal items from law enforcement vehicles or armories. Ammunition is the only exception.","level":0},{"text":"Criminal characters are expected to show realistic fear and awareness of law enforcement at all times. Ambushing police without proper build-up, returning to active scenes, baiting officers or locals, interfering without valid RP reason, or escalating every encounter into violence will be considered Fail RP. You must roleplay with self-preservation and value of freedom in mind - meaning your character recognizes real consequences such as prison time, serious injury, or death, and does not treat LEO action as a minor inconvenience. Killing officers, mass drug crimes, running over police, or acting as a constant menace in every interaction is not realistic and will not be tolerated. Criminal RP should reflect tension, caution, and consequence — not reckless escalation. Repeated menace behavior or disregard for realism will result in disciplinary action for Fail RP.","level":0},{"text":"Players must have at least 7 days of playtime in the city before applying to any law enforcement department.","level":0},{"text":"Faction Air Drops:","level":0},{"text":"LEOs must continue to enforce all State laws, the NHRP Penal Code, and department policies while responding to or operating at an Airdrop.","level":1},{"text":"This includes conducting arrests, investigations, evidence collection, and any other law enforcement duties.","level":1},{"text":"The Airdrop KOS exemption does not excuse LEOs from following department policies or server rules.","level":1},{"text":"Handcuff & Jailbreak Rules","level":0},{"text":"Once a suspect has been placed in handcuffs, a rescue or jailbreak attempt may only involve a maximum of five players who were not part of the original scene. This five-person limit is fixed and cannot be refilled or replaced if rescuers are downed or arrested. Anyone participating in a rescue attempt accepts the risk of being lawfully arrested by law enforcement, and fear of losing your freedom still applies. Even if additional suspects are arrested during the situation, no additional players may join the scene. In simple terms, you get five people for the attempt, and if they fail or are caught, no reinforcements are allowed. Abuse of this rule will result in the privilege being removed and rescue attempts no longer being permitted.","level":0}],"category":"Police / LEO"},{"title":"Contract Heists","items":[{"text":"You may only accept ONE contract at a time.","level":0},{"text":"Farming multiple contracts is not allowed.","level":0},{"text":"If you are caught doing this, you will receive a strike.","level":0}],"category":"General Rules"},{"title":"Cop Baiting","items":[{"text":"Intentionally provoking police (revving, honking, constantly walking away from police after being put in custody, committing crimes in front of them) is not allowed.","level":0},{"text":"New-lifed players cannot return for revenge RP.","level":0}],"category":"Police / LEO"},{"title":"Green Zones","items":[{"text":"Player-owned businesses are the only green zones in NHRP.","level":0},{"text":"All other locations are not considered green zones.","level":0},{"text":"No hiding inside a green zone for protection.","level":0},{"text":"If a scene begins outside a green zone and then enters a player-owned business, the active scene may continue.","level":0},{"text":"Players must be allowed 5 minutes after flying in to get ready for RP.","level":0}],"category":"Crime & Conflict"},{"title":"Tebex Purchased Items","items":[],"category":"EMS / Fire & Media"},{"title":"Aircraft Rules","items":[{"text":"Players must purchase a pilots license through the Tebex.","level":1},{"text":"Sharing the designated in-city purchase code with anyone will result in a permanent ban.","level":1},{"text":"Fixed-wing aircraft may only take off and land on approved runways.","level":1},{"text":"Helicopters may only land on designated helipads or outside city and town limits where doing so will not endanger people or damage property.","level":1},{"text":"EMS helicopters may perform air medical scene responses within the city and town limits, but the pilot must establish and maintain two-way radio communication with on-scene EMS personnel or law enforcement throughout the duration of the response.","level":1},{"text":"LEO helicopters are prohibited from landing to assist with an active scene, exiting the aircraft to participate in the incident, or remaining on scene for any purpose other than the immediate deployment or retrieval of personnel.","level":1}],"category":"Ownership & Purchases"},{"title":"Tebex (F9) Vehicles","items":[{"text":"Cannot be sold or transferred for IRL money. All purchases are final and no refunds will be issued. Use the test drive feature to ensure the vehicle you are looking to purchase satisfies you prior to purchase","level":1}],"category":"Ownership & Purchases"},{"title":"1:1 Guns / F9 Guns","items":[{"text":"Tebex weapons are for personal use only and cannot be shared.","level":1},{"text":"Admins may inspect or revoke Tebex weapons at any time.","level":1},{"text":"F9 weapons may not be bought, sold, or traded using in-game currency in character(IC) with other players.","level":1},{"text":"Weapons must be stored and carried realistically.","level":1},{"text":"1-of-1 weapons are assigned to a single character and may not be duplicated, transferred, or shared with another player or character.","level":1}],"category":"Ownership & Purchases"},{"title":"In Game Televisions","items":[{"text":"To use in-game televisions, you must own the Television Package available through the NHRP Tebex store.","level":1},{"text":"Pornographic, sexually explicit, or otherwise prohibited content may not be displayed on any in-game television under any circumstances.","level":1},{"text":"You may only use a television with permission from the business owner, property owner, or with approval from a member of the staff team.","level":1},{"text":"Use common sense when selecting content. If you are unsure whether something is appropriate, do not play it.","level":1},{"text":"Staff reserve the right to determine whether displayed content is appropriate for the community.","level":1},{"text":"Any violation of these rules may result in the permanent removal of your television privileges without a refund. Additional disciplinary action may be taken depending on the severity of the violation.","level":1},{"text":"All purchases are final. NHRP does not issue refunds for any purchases.","level":0},{"text":"Executive Director and up can revoke ownership of any purchased item for rule violation(s).","level":0},{"text":"NHRP purchased items, donor perks, and Tebex assets are conditional virtual server privileges tied to participation within the community and remain subject to server rules, disciplinary action, Character Kills, wipes, and permanent bans.","level":0}],"category":"Ownership & Purchases"},{"title":"Business Rules","items":[{"text":"Owners must log 10+ hours/week.","level":0},{"text":"Only one purchaser allowed. Only the person who opens the ticket, and makes the purchase to NHRP is recognized as the owner. Private party agreements with others contributors for funds is a private party matter.","level":0},{"text":"Selling a business requires a support ticket.","level":0},{"text":"No refunds for business purchases.","level":0},{"text":"Businesses must remain active to keep ownership. Lack of activity will result in the business being posted for sale and no refund will be issued.","level":0},{"text":"Businesses can be revoked by server management discretion.","level":0},{"text":"Businesses are only allowed if approved by Executive Directors and above.","level":0},{"text":"Server Director and up have the right to revoke business ownership at any time.","level":0},{"text":"No selling or taking IRL money from anyone for transferring ownership or partnership on a business after the original purchase is made.","level":0}],"category":"Ownership & Purchases"},{"title":"Housing Rules","items":[{"text":"Must log 10+ hours/month to retain ownership.","level":0},{"text":"Each character may own only one property","level":0},{"text":"Selling a house requires a support ticket.","level":0},{"text":"IRL Money Paid Houses cannot be sold for IRL or in-game money.","level":0},{"text":"You can only own or rent 1 house per character.","level":0},{"text":"Server Director and up have the right to revoke housing ownership at any time.","level":0},{"text":"Placing furniture items in excessive quantities to block entrances, property lines, yards, or other areas of your property in an unrealistic manner is not permitted. Furniture must be used in a way that is reasonable and consistent with realistic property use.","level":0},{"text":"For example, placing large amounts of carpets, picture frames, or other unrealistic furniture items to block or protect honey hives is not permitted.","level":1}],"category":"Ownership & Purchases"},{"title":"Discord Rules","items":[{"text":"Be respectful to all members and staff.","level":0},{"text":"No spamming chats, channels, or tickets.","level":0},{"text":"No promotion of other servers or Discords unless approved by Server Directors or Owner.","level":0},{"text":"Do not tag roles you do not possess.","level":0},{"text":"Abusing roles will result in removal of role privileges.","level":0},{"text":"Do not ask technical/script questions in general chat or tickets. You will need to find out in character.","level":0}],"category":"Community & Reports"},{"title":"Outside Discords","items":[{"text":"Outside Discords for businesses, factions, or anything pertaining to New Horizons must be fully accessible (admin perms) in all channels and VCs by Owner and Executive Directors and are subject to the same rules as the general NHRP discord.","level":0}],"category":"Community & Reports"},{"title":"Communication","items":[{"text":"Using outside Discords for in-game advantage = Metagaming.","level":0},{"text":"All in-character communication must be face-to-face, phone, or radio, using discord VC for in-character conversation is metagaming..","level":0}],"category":"Community & Reports"},{"title":"Faction Rules","items":[],"category":"Factions & Conflict"},{"title":"Faction Creation & Approval","items":[{"text":"All factions must be officially approved by Executive Directors and purchased through Tebex before operating.","level":0},{"text":"The faction owner is the only person required to pay the real-life purchase cost; members do not pay to join.","level":0},{"text":"New players must be in the city for at least one week before joining a faction.","level":0},{"text":"There is a one-week cooldown before joining another faction after leaving one.","level":0},{"text":"Faction names and tags must be unique and appropriate.","level":0},{"text":"Recruitment must be done in character and in game only. Recruiting through Discord is not permitted.","level":0},{"text":"Factions cannot be used for real-life financial gain.","level":0},{"text":"If a faction owner is banned, commits Random Deathmatch (killing without proper RP), LTAPs (leaves the scene or game to avoid punishment), leaves the server, or is inactive for 30 days, the faction will be put up for sale.","level":0},{"text":"If another member does not purchase the faction, it will be removed or reposted for sale.","level":1},{"text":"No refunds will be issued for faction removals due to rule violations or inactivity.","level":0},{"text":"Roleplaying as a faction without approval, including using default GTA faction clothing without a purchased and approved faction, is considered Fail RP.","level":0},{"text":"Executive Directors and Owner can remove a faction at any time.","level":0}],"category":"Factions & Conflict"},{"title":"Included with Faction Purchase","items":[{"text":"Faction Discord Role","level":0},{"text":"Exclusive Hideout","level":0},{"text":"Territory","level":0},{"text":"Custom Clothing","level":0},{"text":"Stash","level":0},{"text":"Faction Boss Menu","level":0},{"text":"Garage at compound","level":0}],"category":"Factions & Conflict"},{"title":"Territory Rules","items":[{"text":"Territories are pre-determined by server ownership.","level":0},{"text":"First-come, first-served.","level":0},{"text":"All turf wars must be conducted in character (IC).","level":0},{"text":"Faction compounds are not protected from theft or robberies from other factions.","level":0}],"category":"Factions & Conflict"},{"title":"Core Philosophy","items":[{"text":"Our server is built around organic, immersive storytelling. Factions are not just groups—they are living narratives that evolve through player interaction, conflict, and cooperation.","level":0},{"text":"All faction members are expected to:","level":0},{"text":"Prioritize roleplay over winning","level":0},{"text":"Embrace long-term storytelling","level":0},{"text":"Accept both success and failure as part of the narrative","level":0},{"text":"Follow all written rules of NHRP","level":0}],"category":"General Rules"},{"title":"Organic Roleplay Standards","items":[{"text":"No Forced Storylines","level":0},{"text":"You may not force roleplay outcomes on others","level":1},{"text":"Avoid scripting scenarios without room for interaction","level":1},{"text":"Every situation must allow natural player response","level":1},{"text":"Slow Burn RP","level":0},{"text":"Build relationships, rivalries, and reputations over time","level":1},{"text":"Avoid “instant gang” or “overnight empire” mentalities","level":1},{"text":"Progression must feel earned and believable","level":1},{"text":"Value of Life (VoL)","level":0},{"text":"Your character values their life at all times","level":1},{"text":"Avoid reckless or unrealistic behavior","level":1},{"text":"Fear, hesitation, and negotiation are encouraged","level":1}],"category":"General Rules"},{"title":"Internal Faction Conduct","items":[{"text":"Leadership Responsibility","level":0},{"text":"Encourage quality roleplay","level":1},{"text":"Prevent rule-breaking within the faction.","level":1},{"text":"Maintain internal structure and consistency.","level":1},{"text":"Member Expectations","level":0},{"text":"Stay in character at all times.","level":1},{"text":"Respect chain of command.","level":1},{"text":"Contribute to faction storylines.","level":1}],"category":"Factions & Conflict"},{"title":"Conflict & PvP Rules","items":[{"text":"Story First, Combat Second","level":0},{"text":"Conflict must be roleplay-driven, not random","level":1},{"text":"Build tension before escalation","level":1},{"text":"Violence should have context and consequence","level":1},{"text":"Initiation","level":0},{"text":"Clear roleplay interaction must occur before hostile action","level":1},{"text":"No silent attacks or “drive-by RP”","level":1},{"text":"Consequences Matter","level":0},{"text":"Injuries, losses, and defeats must be respected","level":1},{"text":"Avoid “reset mentality” after major events","level":1}],"category":"General Rules"},{"title":"Alliances and Rivalries","items":[{"text":"Organic Relationships","level":0},{"text":"Alliances must form through interaction","level":1},{"text":"Gangs and factions are not permitted to tie flags with another gang or faction.","level":1},{"text":"Rivalries should evolve naturally—not instantly declared","level":1},{"text":"Betrayal and Drama","level":0},{"text":"Allowed and encouraged—but must be roleplay justified","level":1},{"text":"Avoid OOC grudges influencing IC actions","level":1}],"category":"Factions & Conflict"},{"title":"Meta and Powergaming","items":[{"text":"Metagaming and Powergaming is strictly prohibited.","level":0},{"text":"Using out-of-character information (metagaming)","level":1},{"text":"Forcing actions on others without RP (powergaming)","level":1},{"text":"Unrealistic abilities or knowledge","level":1}],"category":"Game Mechanics"},{"title":"Staff Intervention","items":[{"text":"Staff may step in if:","level":0},{"text":"Roleplay becomes non-organic","level":1},{"text":"Rules are repeatedly broken","level":1},{"text":"A faction negatively impacts server health","level":1},{"text":"Possible Actions can include","level":0},{"text":"Warnings","level":1},{"text":"Faction restructuring","level":1},{"text":"30 day Faction Blackball","level":1}],"category":"General Rules"},{"title":"Additional Faction Rules","items":[{"text":"If you work at a player owned business, faction attire cannot be worn while on duty at the business.","level":0},{"text":"Members must leave the faction in-city and in character, leaving the gang in your discord is not roleplay, and your 7 days cooldown to join another faction starts after the interaction of leaving the faction in the city.","level":0},{"text":"Faction Bleed Out: A bleed-out must be carried out through meaningful, cinematic roleplay. Simply taking a former member to your compound and shooting them does not count as a successful bleed-out.","level":0},{"text":"A successful bleed-out must include a developed roleplay scene that clearly establishes the faction’s intent to remove the former member’s faction knowledge.","level":1},{"text":"Once the cinematic bleed-out is completed and the former member is successfully flat-backed or body-bagged by EMS within 7 days of being released from the faction, the player loses all memory of faction-related knowledge.","level":1},{"text":"Receiving roadside treatment from EMS or care from a Black Medic doctor does not prevent the loss of faction-related knowledge after a successful bleed-out.","level":1},{"text":"Factions are prohibited from using any custom mini peds purchased on the Tebex system.","level":0},{"text":"If a faction is engaged in criminal gang related activity, all members must wear their assigned gang/MC Clothing. Operating \"unmarked\" to avoid criminal association or identification is prohibited. All groups/MC's must be in a minimum of a bandana or \"flag\" while doing criminal activity related to the gang.","level":0},{"text":"No Compound Camping: You cannot use your group’s compound as a base or \"safe zone\" during an active priority scene you started. The 5-Minute Rule: After starting a priority scene, you must wait 5 minutes (real-time) before you are allowed to return to your compound.","level":0},{"text":"Graffiti: Graffiti can only be placed in common easily visible areas. Placing graffiti in hard to find or “glitching” the placement will be considered script exploitation and will result in disciplinary action. Spam spraying areas to take a zone is not allowed. There are multiple ways to over take a zone.","level":0},{"text":"There is to be no spraying of graffiti on moving doors. Spraying on moving doors makes the graphic float.","level":1},{"text":"No repetitive robbing or constant targeting.","level":0},{"text":"There should be no killing Civs without proper interaction.  Not everyone on the server is here to interact with the gangs/MC’s.","level":0},{"text":"There will be a 1 hour cool down between faction v faction or LEO. THIS WILL BE STRICTLY ENFORCED.","level":0},{"text":"Anytime you commit a robbery from another faction member the following items can be taken:","level":0},{"text":"Ammo","level":1},{"text":"Guns (excluding F9 Guns)","level":1},{"text":"Drugs or drug making materials","level":1},{"text":"Dirty money","level":1},{"text":"Debit Cards","level":1},{"text":"Cash","level":1},{"text":"Bandages","level":1},{"text":"Repair Kits","level":1},{"text":"Armour","level":1},{"text":"Phone","level":1},{"text":"Radio","level":1},{"text":"Food/Water Items","level":1},{"text":"Any blackmarket or hardware store items.","level":1}],"category":"Factions & Conflict"},{"title":"Violence & Shootouts","items":[{"text":"Must have a valid IC reason.","level":0},{"text":"No Robbing Civs without proper roleplay reason.","level":0},{"text":"Airdrops:","level":0},{"text":"During an active air drop, the marked red zone is considered KOS.","level":1},{"text":"The 1 minute interaction rule does not apply inside the red zone. No snipers during air drops.","level":1},{"text":"No robbing rival players or vehicles inside the air drop redzone or immediately after.","level":1},{"text":"PVP zone is KOS inside the scrapyard walls only. PVP outside of the scrapyard walls will result in a comms. No robbing of players or vehicles is permitted inside the PVP zone.","level":0},{"text":"No RDM/VDM or “Kill on Sight” without RP.","level":0},{"text":"Police RP must be respected and no powergaming and must value your freedom.","level":0},{"text":"Do not have a Winning Mentality, prioritize ROLEPLAY over WINNING.","level":0}],"category":"Factions & Conflict"},{"title":"Weapons & Vehicles","items":[{"text":"Drive-by shootings are generally prohibited and are only allowed in very limited gang-related situations. They may occur only between confirmed gangs with an established rivalry and must have clear prior roleplay  (verbal confrontation, threats, ongoing beef, or turf disputes). Random drive-bys are not allowed, and civilians, EMS, police, and non-gang players may never be targeted. Drive-bys must be approved gang activity (no solo actions), pistols only (no heavy weapons), and vehicles must be driven at realistic speeds (60MPH or Less), no high-speed spraying. A cooldown applies between drive-bys to prevent abuse, and recordings/bodycams are required where applicable for staff review.","level":0},{"text":"No walking around with AR’s unless you're in an active conflict. Using weapons is to be the last resort for all scenes.","level":0}],"category":"Factions & Conflict"},{"title":"Gang Conflicts","items":[{"text":"Must be driven by RP and story.","level":0},{"text":"Server Directors may intervene for balance.","level":0},{"text":"There will be a 60 IRL minute cooldown after ANY gang/MC v gang/MC interaction.","level":0},{"text":"There will be a 60 IRL minute cooldown after ANY priority scene with LEO v faction interaction.","level":0}],"category":"Factions & Conflict"},{"title":"Faction/Gang Discipline","items":[{"text":"Staff Intervention","level":0},{"text":"All faction-related disciplinary actions will be handled exclusively by a Server Director, Executive Director, or Owner. All decisions made are final and are not subject to appeal.","level":1},{"text":"All factions and gangs are subject to a strike policy.","level":1}],"category":"Factions & Conflict"},{"title":"NHRP Chain of Punishment","items":[{"text":"To promote fairness, consistency, accountability, and high-quality roleplay, New Horizons Roleplay utilizes a progressive disciplinary system based around Community Service (“Comms”).","level":0},{"text":"All disciplinary action is handled at staff discretion based on:","level":0},{"text":"Severity of the violation","level":0},{"text":"Prior disciplinary history","level":0},{"text":"Impact on server health","level":0},{"text":"Roleplay quality","level":0},{"text":"Player cooperation during investigations","level":0},{"text":"Intentional malicious behavior","level":0},{"text":"Staff reserve the right to escalate or bypass progression depending on severity.","level":0},{"text":"Community Service (“Comms”) System","level":0},{"text":"Community Service (“Comms”) is the primary form of disciplinary action used within NHRP.","level":0},{"text":"Conversion Rate","level":0},{"text":"10 Sweeps = 10 Minutes of Community Service","level":0},{"text":"Punishment amounts vary depending on the rule violation and severity level.","level":0},{"text":"Progressive Punishment Structure","level":0},{"text":"4th Comms Character Kill (CK) Policy","level":0},{"text":"A player receiving a 4th Comms receives their final disciplinary opportunity and will receive a Full Character Kill (CK).","level":0},{"text":"The assigned Community Service punishment must still be fully completed.","level":0},{"text":"A Character Kill may include:","level":0},{"text":"Full inventory wipe","level":0},{"text":"Loss of all money and assets","level":0},{"text":"Loss of all IRL purchased Tebex/F9 items with NO reimbursement","level":0},{"text":"Removal from all faction ownership","level":0},{"text":"Removal from all business ownership","level":0},{"text":"Immediate termination from EMS, LEO, DOJ, Government, or leadership positions","level":0},{"text":"Forced creation of a completely new character","level":0},{"text":"If a player owns a faction or business:","level":0},{"text":"Ownership may be revoked","level":0},{"text":"The faction/business may be reposted for sale","level":0},{"text":"No refunds or compensation will be issued","level":0},{"text":"A Character Kill represents the final corrective action before permanent removal from the community.","level":0},{"text":"Immediate Permanent Ban Violations","level":0},{"text":"Certain violations are considered severe enough to bypass the progressive Comms system entirely.","level":0},{"text":"These violations may result in an immediate permanent ban without warning, including but not limited to:","level":0},{"text":"Metagaming","level":0},{"text":"Stream Sniping","level":0},{"text":"Cheating / Mod Menus","level":0},{"text":"Exploiting","level":0},{"text":"Tactical Visual Mods","level":0},{"text":"Racism / Hate Speech","level":0},{"text":"Sexual Harassment","level":0},{"text":"Doxxing","level":0},{"text":"Real-Life Threats","level":0},{"text":"Advertising Other Servers","level":0},{"text":"LTAP (Leaving to Avoid Punishment)","level":0},{"text":"Severe malicious community disruption","level":0},{"text":"Staff and server leadership retain full authority regarding permanent ban decisions.","level":0},{"text":"Staff Discretion","level":0},{"text":"All disciplinary action remains subject to staff discretion.","level":0},{"text":"Server Staff, Executive Directors, and Ownership maintain full authority to:","level":0},{"text":"Escalate punishments","level":0},{"text":"Bypass progression systems","level":0},{"text":"Issue permanent bans","level":0},{"text":"Wipe inventories/assets","level":0},{"text":"Remove faction or business ownership","level":0},{"text":"Revoke whitelist access at any time","level":0},{"text":"The purpose of this system is to encourage accountability, realism, and immersive roleplay while still allowing players opportunities to improve behavior before permanent removal from the community.","level":0},{"text":"Matrix for Comms","level":0}],"category":"Discipline & Reference"},{"title":"Disclaimers","items":[{"text":"The rules are subject to change at any time.","level":0},{"text":"All new or updated rules will be highlighted for easy reference.","level":0},{"text":"All purchases are final, NHRP has a no refund policy.","level":0},{"text":"All assets and files included within the server are property of New Horizons Roleplay and are granted as accessible to all players to enjoy and use while within the server. Any assets donated to the server become the property of New Horizons Roleplay. No refunds will be issued if you or the asset are removed or voluntarily leave the community. Any attempt to duplicate, resell, repurpose or in any other way steal these assets is strictly prohibited. Any persons found doing this will be subject to disciplinary action including server bans, reports to CFx, Discord etc. and may be subject to legal action if pursued by the server owner. Any persons who learn of this behavior should make an immediate staff report to the proper chain of command.","level":0},{"text":"This document is property of New Horizons Roleplay. Reproduction of this document without consent of the Owner is prohibited. This document is subject to change, and members are responsible for following all rules and regulations.","level":0}],"category":"Discipline & Reference"}],"progressiveTable":[["Offense Level","Disciplinary Action"],["1st Comms","Formal disciplinary action"],["2nd Comms","Escalated disciplinary action"],["3rd Comms","Severe disciplinary status"],["4th Comms","Final Comms opportunity + All Character Kill (CK) + Inventory Wipe (See information on CK below)"],["5th Offense","Permanent Ban"]],"matrixTable":[["Violation","Tier","1st Comms","2nd Comms","3rd Comms","4th Comms + CK","5th Offense"],["Minor FailRP","1","20 Sweeps","40 Sweeps","80 Sweeps","160 Sweeps + CK","Permanent Ban"],["Severe FailRP","2","60 Sweeps","120 Sweeps","250 Sweeps","500 Sweeps + CK","Permanent Ban"],["Low Quality RP","1","20 Sweeps","50 Sweeps","100 Sweeps","200 Sweeps + CK","Permanent Ban"],["Repetitive RP","1","20 Sweeps","40 Sweeps","80 Sweeps","160 Sweeps + CK","Permanent Ban"],["After Dark RP","1","20 Sweeps","40 Sweeps","80 Sweeps","160 Sweeps + CK","Permanent Ban"],["Intrusive RP","1","25 Sweeps","50 Sweeps","100 Sweeps","200 Sweeps + CK","Permanent Ban"],["Lootboxing RP","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Asset Transferring","3","150 Sweeps","300 Sweeps","600 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Powergaming","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Winning Mentality","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Fear RP / No Value of Life","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Scene Interference","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Retaliation / Revenge RP","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Minor RDM","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Severe RDM","3","250 Sweeps","500 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Mass RDM","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Minor VDM","2","80 Sweeps","160 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Severe VDM","3","200 Sweeps","400 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Combat Mechanic Abuse","3","200 Sweeps","400 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Combat Logging / LTAP","3","5 Day Temp Ban (1st Offense) / Permanent Ban (2nd Offense)","5 Day Temp Ban (1st Offense) / Permanent Ban (2nd Offense)","5 Day Temp Ban (1st Offense) / Permanent Ban (2nd Offense)","5 Day Temp Ban (1st Offense) / Permanent Ban (2nd Offense)","5 Day Temp Ban (1st Offense) / Permanent Ban (2nd Offense)"],["New Life Rule Violation","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Priority Cooldown Violation","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Cop Baiting","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Hostage Rule Violations","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Realistic Driving Violations","1","25 Sweeps","50 Sweeps","100 Sweeps","200 Sweeps + CK","Permanent Ban"],["Menace RP","2","80 Sweeps","160 Sweeps","320 Sweeps","640 Sweeps + CK","Permanent Ban"],["Metagaming","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Stream Sniping","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Cheating / Mod Menu","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Exploiting Bugs","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Tactical Visual Mods","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Racism / Hate Speech","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Sexual Harassment","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Doxxing / IRL Threats","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Advertising Other Servers","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Minor Toxicity","1","20 Sweeps","50 Sweeps","100 Sweeps","200 Sweeps + CK","Permanent Ban"],["Excessive Toxicity","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Harassment","3","250 Sweeps","500 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Ticket Hostility","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Safe Zone Abuse","3","250 Sweeps","500 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Discord Spam / Abuse","1","20 Sweeps","40 Sweeps","80 Sweeps","160 Sweeps + CK","Permanent Ban"],["Role Abuse","2","75 Sweeps","150 Sweeps","300 Sweeps","600 Sweeps + CK","Permanent Ban"],["Outside Discord Metagaming","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["LEO Equipment Abuse","3","200 Sweeps","400 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["LEO Camping Criminal Areas","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Mass Killing LEO","3","250 Sweeps","500 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["EMS Rule Violations","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Stealing EMS Vehicles","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Streamer Rule Violations","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Contract Farming","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Faction Rule Violations","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Faction Recruiting via Discord","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Faction Exploiting","4","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban","Permanent Ban"],["Faction Compound Camping","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Graffiti Exploiting","3","250 Sweeps","500 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Drive-By Rule Violations","3","250 Sweeps","500 Sweeps","800 Sweeps","1000 Sweeps + CK","Permanent Ban"],["Airdrop / PVP Rule Violations","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Gang Cooldown Violations","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Business Rule Violations","2","100 Sweeps","200 Sweeps","400 Sweeps","800 Sweeps + CK","Permanent Ban"],["Housing Rule Violations","1","25 Sweeps","50 Sweeps","100 Sweeps","200 Sweeps + CK","Permanent Ban"],["Improper Furniture Placement","1","25 Sweeps","50 Sweeps","100 Sweeps","200 Sweeps + CK","Permanent Ban"]]};
